import {overrideProfile} from './override-profile.js';
export const profile=overrideProfile;
const text=(label:string,value='',id='')=>`<div><div>${label}</div><div><div><label class="string_info"><input id="${id}" value="${value}"><div class="sd-Input-message-fixture">必填项未填写 / Required items are not filled in</div></label></div></div></div>`;
const proxy=(value:string)=>`<div><div><div><label><span class="sd-Input-display-value-fixture">${value}</span><input readonly></label></div></div></div>`;
const education=(name:string,degree:string)=>`<div class="record-fixture"><div><div>就读时间 / Education period *</div><div><div class="month-range-select date_info"><span>${proxy('2025')}${proxy('9')}</span><span>-</span><span>${proxy('2027')}${proxy('6')}</span></div></div></div><div><div>学校名称 / School *</div>${proxy(name+' / Fictional University')}</div><div><div>学历 / Degree *</div>${proxy(degree)}</div>${text('GPA/CGPA *','','gpa-'+name)}</div>`;
export const html=`<meta charset="utf-8"><form onsubmit="window.submits++;return false" oninput="window.events++" onchange="window.events++" onclick="window.events++"><div><div>个人信息 / Personal info</div><div>${text('姓名 / Name *',profile.fullName,'name')}${text('所在地 / Location *','','city')}${text('是否需要工作签证 / Work visa required *','','visa')}</div></div><div id="education"><div>教育背景 / Education <button type="button" onclick="const g=document.querySelector('.record-fixture').cloneNode(true);g.querySelectorAll('.sd-Input-display-value-fixture').forEach(e=>e.textContent='');this.parentElement.parentElement.append(g)">添加 / Add</button></div>${education('虚构甲大学','硕士 / Master')}${education('虚构乙大学','本科 / Bachelor')}</div><div><div>实习经历 / Internship experience <button type="button">添加 / Add</button></div><div>${text('公司名称 / Company','虚构研究中心','company')}${text('职位名称 / Job title','','role')}<div><div>工作职责 / Responsibilities</div><div><div><textarea id="description">网站解析错误内容</textarea></div></div></div></div></div><button>预览并提交 / Preview and submit</button></form><script>window.events=0;window.submits=0;</script>`;
export const expectedDOM={role:profile.career!.internships[0]!.role,description:profile.career!.internships[0]!.description};
